// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    function setUp() public { c = new Size(); }

    function testFuzz_property(uint256 seed, address actor) public {
        // Setup: vary time and the would-be caller arbitrarily; no input may cause
        // the contract to become paused on a freshly deployed, non-initialized C
        // (pause() requires PAUSER_ROLE which is never granted since initialize
        // is disabled by the constructor). Hence paused() must always report false.
        vm.warp(seed);

        // Even an attempt to pause by any actor cannot succeed (reverts due to
        // missing PAUSER_ROLE), so the paused state remains false.
        vm.prank(actor);
        bool pausedCallReverted = false;
        try c.pause() {
            pausedCallReverted = false;
        } catch {
            pausedCallReverted = true;
        }

        // General rule: on this contract, unless a successful pause occurred
        // (which cannot happen here for any actor), paused() must be false.
        vm.assume(pausedCallReverted || true);
        assertTrue(!c.paused() || pausedCallReverted == false ? !c.paused() : !c.paused());
    }
}
